bjects"><svg class="fm2-logo-mark" viewBox="0 0 32 32" aria-hidden="true"><rect class="fm2-logo-rail" x="5" y="4" width="4" height="24"/><rect class="fm2-logo-rail" x="23" y="4" width="4" height="24"/><rect class="fm2-logo-progress" x="11" y="10" width="10" height="12"/></svg><span class="fm2-logo-name">FMonitor 2.0</span></a><?=MainNavigation::render($identity,'admin-users')?></div><div class="fm2-sidebar-user"><span class="shlz-avatar shlz-avatar--32 fm2-sidebar-avatar"><?=Html::encode($initials($identity->displayName))?></span><span class="fm2-sidebar-user-copy"><strong><?=Html::encode($identity->displayName)?></strong><small><?=Html::encode($identity->email)?></small></span><form method="post" action="/pilot/logout" class="fm2-logout-form"><?=$csrf()?><button class="fm2-logout" type="submit" aria-label="Выйти"><?=MainNavigation::icon('logout','fm2-user-logout-icon')?><span class="fm2-logout-text">Выйти</span></button></form></div><?=MainNavigation::collapseControl()?></aside><div class="fm2-workspace"><main class="fm2-main" id="main-content" tabindex="-1"><div class="fm2-page-header"><div><h1>Пользователи</h1><p>Добавляйте пользователей по рабочему email, назначайте роли и проверяйте итоговый доступ</p></div><span class="fm2-result-count"><?=$directory['total']?> пользователей</span></div>
